-- More thought-provoking, funny, everyday Naija reasoning for Quick Fire.
insert into public.arena_quickfire_sets(title,description,status)
select 'Quick Fire: Naija Brain & Banter','Funny everyday dilemmas, practical judgement, logic and questions that make you pause before laughing.','published'
where not exists(select 1 from public.arena_quickfire_sets where title='Quick Fire: Naija Brain & Banter');
with q(position,question_text,options,correct_index,explanation,difficulty) as (values
(1,'Your friend says “I am five minutes away” but has not entered the bathroom. What is the safest estimate?', '["They are already outside","Prepare for a documentary","They may need more time","Call the police"]'::jsonb,2,'People use time loosely. Ask for a realistic update rather than planning around a guess.','easy'),
(2,'You receive a message saying you won a prize you never entered. What should you do first?', '["Send your bank PIN","Click every link","Verify through the official organisation","Forward it to your contacts"]'::jsonb,2,'Unexpected prizes are a common scam tactic. Verify independently and never share PINs.','easy'),
(3,'A person says “I am not angry” while arranging your full family history. What is the best response?', '["Listen calmly and ask what is wrong","Start a debate","Laugh loudly","Add more accusations"]'::jsonb,0,'Calm questions help uncover the real issue better than escalating the moment.','easy'),
(4,'You have ₦5,000 for the week and spend ₦4,900 on snacks on Monday. What is the main problem?', '["The snacks are too delicious","The plan has no room for essentials","Monday is unlucky","The money will multiply"]'::jsonb,1,'A budget should protect essential needs before optional spending.','easy'),
(5,'Your phone battery is at 2%, and someone starts a 45-minute voice note. What is the most practical move?', '["Find power or ask for a text summary","Increase screen brightness","Open ten apps","Start recording a movie"]'::jsonb,0,'Choose the communication method that fits your available battery and time.','easy'),
(6,'A friend asks for honest feedback on an idea. The idea has a serious weakness. What is kindest?', '["Insult the idea","Pretend it is perfect","Explain the weakness and suggest an improvement","Tell everybody else first"]'::jsonb,2,'Honesty with useful suggestions is more helpful than flattery or humiliation.','easy'),
(7,'If a shop gives you too much change by mistake, what is the fairest action?', '["Keep quiet and celebrate","Return the extra amount","Blame the next customer","Spend it quickly"]'::jsonb,1,'Fairness means correcting an accidental overpayment.','easy'),
(8,'Your group project has 8 people, but only 2 are working. What should happen next?', '["Clarify tasks and deadlines","Remove everyone from the group","Do all the work silently","Send only angry emojis"]'::jsonb,0,'Clear ownership and deadlines make participation visible and fair.','easy'),
(9,'Someone forwards shocking news with “share before they delete it”. What is the smartest first step?', '["Forward immediately","Check reliable sources","Add more dramatic details","Assume it is true"]'::jsonb,1,'Urgency and emotional language are reasons to verify, not reasons to rush.','easy'),
(10,'You are late and your excuse is becoming longer than the journey. What is the best response?', '["Give a brief honest update and an ETA","Invent traffic on every road","Stop replying","Blame the weather forecast"]'::jsonb,0,'A concise, truthful update helps others make plans.','easy'),
(11,'A business doubles its price and loses half its customers. What should the owner examine before celebrating?', '["Whether total profit and costs improved","The colour of the signboard","The number of emojis online","Whether competitors are sleeping"]'::jsonb,0,'Revenue, costs, margins and customer retention matter more than one headline number.','standard'),
(12,'You disagree with someone you respect. Which question is most likely to improve the conversation?', '["What evidence would change our minds?","Why are you always wrong?","Can we shout louder?","Who has more followers?"]'::jsonb,0,'A testable question shifts discussion from ego toward evidence.','standard'),
(13,'A friend always asks for advice but ignores it. What boundary is reasonable?', '["Refuse to ever speak again","Ask whether they want listening or advice","Make decisions for them","Post their problems publicly"]'::jsonb,1,'Clarifying what support they want can prevent frustration while respecting their choice.','standard'),
(14,'You have two job offers: one pays more but has unclear duties; the other pays less with clear growth. What should you compare?', '["Total value, risks, learning and priorities","Only the office paint","Which friend will be jealous","The company slogan alone"]'::jsonb,0,'A good decision weighs compensation, conditions, learning and personal priorities.','standard'),
(15,'A viral post has thousands of likes. What does that prove?', '["It is definitely true","It is popular with those who engaged","It is officially verified","It cannot be misleading"]'::jsonb,1,'Popularity is not the same as accuracy or verification.','standard'),
(16,'Your team keeps missing deadlines despite working hard. What is a useful diagnosis?', '["Check workload, priorities and blockers","Buy everyone a louder alarm","Blame the newest person","Add more meetings without a goal"]'::jsonb,0,'Missed deadlines often point to planning, capacity or dependency problems.','standard'),
(17,'A customer complains loudly but makes one valid point. What should a good business do?', '["Address the valid issue calmly","Argue about their volume","Delete the review","Insult their shoes"]'::jsonb,0,'Separate the useful feedback from the delivery and respond professionally.','standard'),
(18,'You discover your confident answer was wrong. What shows good judgement?', '["Correct it openly","Defend it forever","Change the subject","Blame autocorrect"]'::jsonb,0,'Updating a belief when evidence changes is a strength, not a weakness.','standard'),
(19,'A friend wants to borrow money you cannot afford to lose. What is the healthiest answer?', '["Set an honest boundary","Borrow elsewhere secretly","Say yes and resent them","Avoid all messages"]'::jsonb,0,'Do not promise money that would put your own essentials at risk.','standard'),
(20,'A plan works only if nobody makes a mistake. What does it need?', '["A backup plan and realistic margin","More confidence quotes","A longer title","A lucky playlist"]'::jsonb,0,'Robust plans account for uncertainty and ordinary human error.','standard'),
(21,'A town has 100 voters. 60 vote for A, 50 for B, and some voted for both in a survey. What can you conclude?', '["The survey rules need clarification","A definitely won","B definitely won","There were 110 different voters"]'::jsonb,0,'If multiple selections are allowed, totals can exceed the number of people.','expert'),
(22,'A product has a 20% discount, then its discounted price is increased by 20%. Is it back to the original price?', '["Yes, always","No, it is 4% lower","No, it is 4% higher","There is not enough information"]'::jsonb,1,'100 reduced by 20% is 80; increasing 80 by 20% gives 96.','expert'),
(23,'Three people finish a task in 6 hours at the same rate. How long would six people take, assuming perfect scaling?', '["3 hours","6 hours","9 hours","12 hours"]'::jsonb,0,'Doubling the workers halves the time under the stated ideal assumption.','expert'),
(24,'A claim is supported by one personal story and contradicted by several high-quality studies. What is the strongest approach?', '["Weigh the quality and totality of evidence","Treat every source equally","Choose the most emotional story","Ignore all uncertainty"]'::jsonb,0,'Evidence quality and the broader body of research matter more than one anecdote.','expert'),
(25,'A company reports record sales but cannot pay suppliers. Which issue may explain this?', '["Cash-flow timing or unpaid receivables","Too many customers smiling","The logo is outdated","Sales are always profit"]'::jsonb,0,'A profitable-looking sales figure does not guarantee cash is available when bills fall due.','expert'),
(26,'A poll has 40 votes: 18 for A, 12 for B, and 10 for C. What percentage chose A?', '["35%","40%","45%","50%"]'::jsonb,2,'18 divided by 40 is 0.45, or 45%.','expert'),
(27,'You can either solve a recurring problem once or keep treating its symptoms daily. Which principle applies?', '["Address the root cause","Choose the loudest symptom","Avoid measurement","Add more reminders forever"]'::jsonb,0,'Root-cause thinking aims to prevent repeated failures.','expert'),
(28,'A friend says a decision is good because “we have already spent too much to stop”. What bias is this?', '["Sunk-cost fallacy","Survivorship bias","Confirmation bias","Availability heuristic"]'::jsonb,0,'Past unrecoverable costs should not determine whether a future choice is worthwhile.','expert'),
(29,'A survey gets 1,000 replies, all from one fan club. What is the biggest limitation?', '["The sample may not represent the wider population","The sample is automatically perfect","The results prove everyone agrees","The number of replies removes all bias"]'::jsonb,0,'A large biased sample can still produce unrepresentative results.','expert'),
(30,'A leader receives only good news because people fear disagreeing. What is the greatest risk?', '["Blind spots and poor decisions","Faster learning","Perfect accuracy","No need for feedback"]'::jsonb,0,'Psychological safety and honest feedback help leaders detect problems early.','expert')
), s as (select id from public.arena_quickfire_sets where title='Quick Fire: Naija Brain & Banter' limit 1),
i as (
 insert into public.arena_quickfire_questions(set_id,question_text,options,position,points,difficulty)
 select s.id,q.question_text,q.options,q.position,10,q.difficulty
 from q cross join s
 where not exists(select 1 from public.arena_quickfire_questions old where old.set_id=s.id and old.question_text=q.question_text)
 returning id,position
)
insert into private.arena_quickfire_answer_keys(question_id,correct_option_index,explanation)
select i.id,q.correct_index,q.explanation from i join q using(position)
on conflict(question_id) do nothing;
